SELECT carrier, cost_bucket, min_cost, avg_cost FROM (SELECT carrier, CASE WHEN cost >= 90 THEN 'high' WHEN cost >= 18 THEN 'mid' ELSE 'low' END AS cost_bucket, MIN(cost) AS min_cost, AVG(cost) AS avg_cost FROM shipments GROUP BY carrier, CASE WHEN cost >= 90 THEN 'high' WHEN cost >= 18 THEN 'mid' ELSE 'low' END) AS t WHERE avg_cost >= 40 ORDER BY cost_bucket, carrier DESC LIMIT 20;
